// ============================================================
// UKCCU MEDIA RENDERER
// Reads mediaData from media-data.js and renders all sections.
// Do not edit this file to manage content. Edit media-data.js.
// ============================================================

document.addEventListener("DOMContentLoaded", function () {

    // ---- GALLERY ----

    function getCategoryLabel(category) {
        const labels = {
            sunday: "Sunday",
            friday: "Friday",
            outreach: "Outreach"
        };
        return labels[category] || category;
    }

    function renderGallery(items) {
        var container = document.getElementById("gallery-container");
        if (!container) return;

        container.innerHTML = "";

        items.forEach(function (item) {
            var col = document.createElement("div");
            col.className = "col-lg-4 col-md-6 gallery-item " + item.category;

            col.innerHTML =
                '<div class="gallery-card">' +
                    '<div class="gallery-image-wrapper">' +
                        '<img src="' + item.image + '" alt="' + item.alt + '" />' +
                        '<span class="gallery-badge">' + item.badge + '</span>' +
                    '</div>' +
                    '<div class="gallery-content">' +
                        '<h5>' + item.title + '</h5>' +
                        '<p>' + item.description + '</p>' +
                        '<div class="gallery-actions">' +
                            '<a class="btn btn-primary btn-sm" href="' + item.albumLink + '" target="_blank">' +
                                '<i class="fas fa-images me-1"></i> View Album' +
                            '</a>' +
                        '</div>' +
                    '</div>' +
                '</div>';

            container.appendChild(col);
        });
    }

    function initGalleryFilters() {
        var filterButtons = document.querySelectorAll("#gallery-filters li");

        filterButtons.forEach(function (button) {
            button.addEventListener("click", function () {
                var filterValue = this.getAttribute("data-filter");

                filterButtons.forEach(function (btn) {
                    btn.classList.remove("active");
                });
                this.classList.add("active");

                var galleryItems = document.querySelectorAll(".gallery-item");

                galleryItems.forEach(function (item) {
                    if (filterValue === "*") {
                        item.style.display = "block";
                        setTimeout(function () {
                            item.style.opacity = "1";
                            item.style.transform = "scale(1)";
                        }, 10);
                    } else {
                        var filterClass = filterValue.substring(1);
                        if (item.classList.contains(filterClass)) {
                            item.style.display = "block";
                            setTimeout(function () {
                                item.style.opacity = "1";
                                item.style.transform = "scale(1)";
                            }, 10);
                        } else {
                            item.style.opacity = "0";
                            item.style.transform = "scale(0.9)";
                            setTimeout(function () {
                                item.style.display = "none";
                            }, 300);
                        }
                    }
                });
            });
        });

        document.querySelectorAll(".gallery-item").forEach(function (item) {
            item.style.transition = "opacity 0.3s ease, transform 0.3s ease";
        });
    }

    // ---- RESOURCES ----

    function renderResources(items) {
        var container = document.getElementById("resources-container");
        if (!container) return;

        container.innerHTML = "";

        items.forEach(function (item, index) {
            var delay = (index + 1) * 0.2;
            var col = document.createElement("div");
            col.className = "col-lg-4 col-md-6 wow fadeInUp";
            col.setAttribute("data-wow-delay", delay + "s");

            col.innerHTML =
                '<div class="resource-card">' +
                    '<div class="resource-image-wrapper" style="background: ' + item.gradient + ';">' +
                        '<img src="' + item.image + '" alt="' + item.alt + '" />' +
                        '<i class="' + item.icon + ' resource-icon"></i>' +
                    '</div>' +
                    '<div class="resource-content">' +
                        '<h5>' + item.title + '</h5>' +
                        '<p>' + item.description + '</p>' +
                        '<a href="' + item.link + '" class="resource-link">' +
                            'Explore Resources <i class="fas fa-arrow-right"></i>' +
                        '</a>' +
                    '</div>' +
                '</div>';

            container.appendChild(col);
        });
    }

    // ---- DOCUMENTS ----

    function renderDocuments(items) {
        var container = document.getElementById("documents-container");
        if (!container) return;

        container.innerHTML = "";

        items.forEach(function (item) {
            var col = document.createElement("div");
            col.className = "col-md-6 col-lg-4";

            col.innerHTML =
                '<div class="bg-white rounded p-3">' +
                    '<i class="' + item.icon + ' fa-3x text-primary mb-3"></i>' +
                    '<h5 class="mb-2">' + item.title + '</h5>' +
                    '<p class="small text-muted mb-3">' + item.description + '</p>' +
                    '<p class="small text-muted">File Size: ' + item.fileSize + ' | Last Updated: ' + item.lastUpdated + '</p>' +
                    '<div class="d-flex justify-content-center gap-2 mt-3">' +
                        '<a href="' + item.downloadLink + '" class="btn btn-primary btn-sm" download>' +
                            '<i class="fas fa-download me-2"></i>Download' +
                        '</a>' +
                    '</div>' +
                '</div>';

            container.appendChild(col);
        });
    }

    // ---- INIT ----

    if (typeof mediaData !== "undefined") {
        renderGallery(mediaData.galleryItems || []);
        initGalleryFilters();
        renderResources(mediaData.resourceItems || []);
        renderDocuments(mediaData.documentItems || []);
    }

});